    "effectZh": "[Raid]\n〈利姆鲁〉激活状态，可移动至前线L\n[启动主效果]\n[当前位于前线L时]\n[回合 1]\n选择自己场上除〈利姆鲁〉外原本 BP 为 4000 以上的角色卡 1 张，直到下一个自己的回合开始为止，使其失去所有原本的卡牌效果并抽 1 张牌。\n[启动主效果]\n[当前位于前线L时]\n[回合 1]\n选择对方前线 L 中 BP 为 1500 以上的角色卡最多 1 张，本回合内其 BP-1000。若自己场外有原本 BP 4000 以上的角色卡牌 4 张以上，可将手牌中的 1 张置于场外。如此操作时，可选择自己能量 L 的角色卡最多 1 张并移动至前线L。",
    "trigger": "[レイド]\nこのカードを手札に加えるか、必要エナジーを満たしている場合、レイドさせる。",
